public final class ApiTest {
    private ApiTest() {}

    public static void main(String[] args) {
        try {
            String grid_png = "/Users/clockorangezoe/Documents/phd_projects/code/geoAI/GRAIL_thumbnailator_A1/experiments/external/thumbnailator/source/src/test/resources/Thumbnailator/grid.png";
    String grid_jpeg = "/Users/clockorangezoe/Documents/phd_projects/code/geoAI/GRAIL_thumbnailator_A1/experiments/external/thumbnailator/source/src/test/resources/Thumbnailator/grid.jpg";
    String exif_jpeg = "/Users/clockorangezoe/Documents/phd_projects/code/geoAI/GRAIL_thumbnailator_A1/experiments/external/thumbnailator/source/src/test/resources/Exif/original.jpg";
    String output_dir = "/Users/clockorangezoe/Documents/phd_projects/code/geoAI/GRAIL_thumbnailator_A1/experiments/external/thumbnailator/.aideal_exec/A1/output";

    // pre-loaded typed inputs (comprehension.execute.preamble)
    BufferedImage sourceImage = new BufferedImage(32, 24, BufferedImage.TYPE_INT_RGB);
    Graphics2D graphics = sourceImage.createGraphics();
    graphics.setColor(Color.BLUE);
    graphics.fillRect(0, 0, 32, 24);
    graphics.setColor(Color.YELLOW);
    graphics.fillRect(8, 6, 16, 12);
    graphics.dispose();
    BufferedImage destinationImage = new BufferedImage(16, 12, BufferedImage.TYPE_INT_RGB);
    ByteArrayOutputStream imageBytes = new ByteArrayOutputStream();
    Path outputPath = Paths.get(output_dir, "thumbnail.png");
    Files.createDirectories(outputPath.getParent());

            // TODO API_TEST_START
            net.coobird.thumbnailator.filters.ImageFilter addFilter = new net.coobird.thumbnailator.filters.ImageFilter() {
                @Override
                public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage img) {
                    return new java.awt.image.BufferedImage(img.getWidth() + 5, img.getHeight() + 5, java.awt.image.BufferedImage.TYPE_INT_ARGB);
                }
            };

            net.coobird.thumbnailator.filters.ImageFilter multFilter = new net.coobird.thumbnailator.filters.ImageFilter() {
                @Override
                public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage img) {
                    return new java.awt.image.BufferedImage(img.getWidth() * 2, img.getHeight() * 2, java.awt.image.BufferedImage.TYPE_INT_ARGB);
                }
            };

            net.coobird.thumbnailator.filters.Pipeline pipeline = new net.coobird.thumbnailator.filters.Pipeline();
            pipeline.add(multFilter);
            pipeline.addFirst(addFilter);

            java.awt.image.BufferedImage result = pipeline.apply(sourceImage);

            int expectedWidth = (sourceImage.getWidth() + 5) * 2;
            int expectedHeight = (sourceImage.getHeight() + 5) * 2;

            assert result.getWidth() == expectedWidth : "Expected width " + expectedWidth + " but got " + result.getWidth();
            assert result.getHeight() == expectedHeight : "Expected height " + expectedHeight + " but got " + result.getHeight();
            assert pipeline.getFilters().size() == 2 : "Expected 2 filters in pipeline";
            assert pipeline.getFilters().get(0) == addFilter : "First filter should be addFilter due to addFirst()";

            System.out.println("__CHECK__ Pipeline " + result.getWidth() + "x" + result.getHeight() + " with " + pipeline.getFilters().size() + " filters");
            // TODO API_TEST_END
            System.out.println("__DONE__");
        } catch (Throwable exc) {
            System.err.println("__RUN_ERR__ " + exc.getClass().getSimpleName()
                    + ": " + exc.getMessage());
            exc.printStackTrace(System.err);
            System.exit(1);
        }
    }
}
